use omarchy_t3_client::*;use serde_json::{json,Value};use std::{fs,io::{Read,Write},net::TcpListener,os::unix::fs::{PermissionsExt,MetadataExt},thread};
#[test]
fn image_history_keeps_descriptor_and_uses_private_signed_cache(){
 let root=std::env::temp_dir().join(format!("t3-image-{}",uuid::Uuid::new_v4()));fs::create_dir_all(&root).unwrap();std::env::set_var("XDG_CACHE_HOME",&root);let token=root.join("token");fs::write(&token,"synthetic-secret-token").unwrap();fs::set_permissions(&token,fs::Permissions::from_mode(0o600)).unwrap();let listener=TcpListener::bind("127.0.0.1:0").unwrap();let config=root.join("env.json");fs::write(&config,json!({"environments":[{"id":"fixture","name":"Fixture","base_url":format!("http://{}",listener.local_addr().unwrap()),"token_file":token}]}).to_string()).unwrap();std::env::set_var("OMARCHY_T3_FIXTURE_ENVIRONMENTS",config);
 let server=thread::spawn(move||{let (s,_)=listener.accept().unwrap();let mut ws=tungstenite::accept(s).unwrap();let req:Value=serde_json::from_str(ws.read().unwrap().to_text().unwrap()).unwrap();assert_eq!(req["tag"],"assets.createUrl");assert_eq!(req["payload"]["resource"]["attachmentId"],"image1");assert_eq!(req["payload"]["resource"]["mimeType"],"image/png");ws.send(tungstenite::Message::Text(json!({"_tag":"Exit","requestId":"1","exit":{"_tag":"Success","value":{"relativeUrl":"/api/assets/signed-image?signature=synthetic","expiresAt":9999999999999u64}}}).to_string().into())).unwrap();let (mut s,_)=listener.accept().unwrap();let mut bytes=[0;8192];let n=s.read(&mut bytes).unwrap();let header=String::from_utf8_lossy(&bytes[..n]).to_lowercase();assert!(header.starts_with("get /api/assets/signed-image?signature=synthetic "));assert!(!header.contains("authorization:"));let image=b"\x89PNG\r\n\x1a\nfixture";write!(s,"HTTP/1.1 200 OK\r\nContent-Type: image/png\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",image.len()).unwrap();s.write_all(image).unwrap();});
 let attachment=json!({"type":"image","id":"image1","name":"shot.png","mimeType":"image/png","sizeBytes":15});let input=json!({"environment":"fixture","attachment":attachment});let result=images::load(&input).unwrap();server.join().unwrap();let url=reqwest::Url::parse(result["url"].as_str().unwrap()).unwrap();assert_eq!(url.scheme(),"file");let path=url.to_file_path().unwrap();assert_eq!(fs::read(&path).unwrap(),b"\x89PNG\r\n\x1a\nfixture");assert_eq!(fs::metadata(&path).unwrap().mode()&0o777,0o600);assert_eq!(images::load(&input).unwrap(),result);
 let doc="<!DOCTYPE HTML><html><head><meta name=\"qrichtext\" content=\"1\" /></head><body><p>Hello &amp; world</p></body></html>";let history=normalize_messages(&json!({"projection":{"thread":{},"messages":[{"id":"m","role":"user","text":doc,"attachments":[attachment]}]}})).unwrap();assert_eq!(history["messages"][0]["text"],"Hello & world");assert_eq!(history["messages"][0]["attachments"][0]["id"],"image1");assert!(!result.to_string().contains("synthetic"));fs::remove_dir_all(root).unwrap();
}
